''' This is a simple script to practice my knowledge of Numpy by analyzing students grades in some subjects.'''

import numpy as np

# data was randomly generated by AI
students = np.array(["Ada", "Tunde", "Chioma", "Ibrahim", "Ngozi", "Femi", "Zainab", "Emeka"])
subjects = np.array(["Maths", "English", "Physics", "Chemistry", "Biology"])
scores = np.array([
    [78, 85, 72, 69, 80],
    [92, 74, 88, 81, 79],
    [65, 90, 58, 62, 71],
    [83, 68, 79, 85, 74],
    [57, 77, 63, 55, 68],
    [88, 82, 91, 87, 90],
    [71, 95, 66, 73, 84],
    [60, 58, 70, 64, 59],
])


# Each students average score across all subjects
student_averages = np.mean(scores, axis=1)
print("Student Averages:")
print(student_averages, "\n")


# Each subjects average score across all students
subject_averages = np.mean(scores, axis=0)
print("Subject Averages:")
print(subject_averages, "\n")


# Standard deviation per subject
subject_std_dev = np.std(scores, axis=0)
print("Subject Standard Deviations:")
print(subject_std_dev, "\n")


# Subject with the most spread in scores
pos = np.argmax(subject_std_dev)
print("Subject with most spread:", subjects[pos], "\n")


# Overall top student
top_student_pos = np.argmax(student_averages)
print("Top Student:", students[top_student_pos], "with average score of", student_averages[top_student_pos], "\n")


# Best student in each subject
best_student_idx = np.argmax(scores, axis=0)
best_score = scores[best_student_idx, np.arange(5)]
print("Best Students in Each Subject:")
for subject, student, score in zip(subjects, students[best_student_idx], best_score):
    print("Best student in", subject, "is", student, "with score", score)

   
# Calculate z-score for each subject score
z_score = (scores - subject_averages) / subject_std_dev
print("Z-Scores:")
print(z_score, "\n")


# Bonus 5 marks for Physics with scores clipped at 100
scores_copy = scores.copy()
scores_copy[:, 2] += 5
clipped_scores = np.clip(scores_copy, 0, 100)
print(clipped_scores, "\n")


# Boolean Masking
# Students with at least one score less than 60
score_threshold = scores < 60
student_mask = score_threshold.any(axis=1)
students_below_60 = students[student_mask]
print(students_below_60, "\n")